function getNestedOptionsByString(key, optionsArray) {
  // Use reduce to iterate over the array of options
  const result = optionsArray.reduce((acc, curr) => {
    // Check if the current object has a property matching the key
    if (curr && Object.keys(curr).includes(key)) {
      // If it does, add the entire option to the accumulator
      acc.push(curr);
    }
    return acc;
  }, []);

  return result;
}

